class Program {
 [STAThread] static int Main(string[] args){try{if(args.Contains("--regions-only")){RegionRuntimeChecks.Run((ok,name)=>{if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);});return 0;}if(args.Contains("--normalization-only")){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};NormalizedRoiChecks.Run();app.Shutdown();return 0;}if(args.Contains("--host-only")){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};System.Threading.SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(app.Dispatcher));RealBinaryHostChecks.Run((ok,name)=>{if(!ok)throw new Exception(name);Console.WriteLine("PASS "+name);});app.Shutdown();return 0;}Run();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static IEnumerable<DependencyObject> Descendants(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var item in Descendants(VisualTreeHelper.GetChild(root,i)))yield return item;}
 static void Run(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int count=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}RegionRuntimeChecks.Run(Check);var plugin=new ImageBinaryPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value);values["LowThreshold"]=JsonSerializer.SerializeToElement(100);values["HighThreshold"]=JsonSerializer.SerializeToElement(150);var pixels=Enumerable.Range(0,256).Select(i=>(byte)i).ToArray();var image=new GrayImage(16,16,pixels);var node=new NodeDocument("binary",ImageBinaryPlugin.Id,"1.0.0","图像二值化1",values);var runtime=plugin.CreateRuntime();ModuleResult Execute(IReadOnlyList<RoiDocument> rois,GrayImage? mask=null){var inputs=new Dictionary<string,PortValue>{{"Image",PortValue.Image(image)}};if(mask is not null)inputs["InputMask"]=PortValue.Image(mask);return runtime.ExecuteAsync(new(node.Id,".",inputs,values,rois),default).Result;}
 var root=Path.GetFullPath("analysis/full-audit/roi-binary-native-probe");var rect=new RoiDocument("r",RoiKind.Rectangle,8,8,8,6);var poly=new RoiDocument("p",RoiKind.Polygon,0,0,Vertices:[new(3,3),new(12,3),new(10,12),new(4,10)]);foreach(var pair in new[]{("full",Array.Empty<RoiDocument>()),("rectangle",new[]{rect})}){using var stream=File.OpenRead(Path.Combine(root,pair.Item1+".bmp"));var native=VisionIO.BmpReader.Read(stream);var ours=Execute(pair.Item2).Outputs["Image"].As<GrayImage>();Check(native.Pixels.SequenceEqual(ours.Pixels),"native pixel comparison "+pair.Item1);}
 values["LowThreshold"]=JsonSerializer.SerializeToElement(0);values["HighThreshold"]=JsonSerializer.SerializeToElement(255);foreach(var pair in new[]{("rectangle-mask",rect),("polygon-mask",poly)}){using var stream=File.OpenRead(Path.Combine(root,pair.Item1+".bmp"));var native=VisionIO.BmpReader.Read(stream);var ours=Execute([pair.Item2]).Outputs["Image"].As<GrayImage>();var difference=native.Pixels.ToArray().Zip(ours.Pixels.ToArray()).Count(p=>p.First!=p.Second);Console.WriteLine("Native differences "+pair.Item1+": "+difference);Check(difference==0,"native coverage "+pair.Item1);}
 values["NonROIPrcType"]=JsonSerializer.SerializeToElement(1);var outside=Execute([rect]);Check(outside.Outputs["Image"].As<GrayImage>()[0,1]==16,"outside source preserved");Check(outside.Outputs["ProcessedPixels"].As<long>()==48,"rectangle processed pixel count");var excluded=poly with{Exclusion=true};Check(Execute([rect,excluded]).Outputs["ProcessedPixels"].As<long>()<48,"polygon exclusion consumed by real algorithm");values["ROIAreaType"]=JsonSerializer.SerializeToElement(1);Check(Execute([rect],new GrayImage(16,16,new byte[256])).Outputs["ProcessedPixels"].As<long>()==0,"input mask consumed");values["ROIAreaType"]=JsonSerializer.SerializeToElement(0);Check(Execute([new("bad",RoiKind.Circle,8,8,Radius:3)]).Status==ModuleStatus.Failed,"unsupported shape rejected");
 var rasterResults=new List<object>();foreach(var csv in Directory.GetFiles("analysis/full-audit/sector-raster-probe","cases*.csv")){foreach(var line in File.ReadAllLines(csv).Skip(1)){var parts=line.Split(',');double Number(int i)=>double.Parse(parts[i],System.Globalization.CultureInfo.InvariantCulture);int size=Path.GetFileName(csv).Contains("16")?16:64;var region=new RoiDocument("sector",RoiKind.Sector,Number(1),Number(2),Radius:Number(4),InnerRadius:Number(3)){Shape=new(StartAngle:Number(5),SweepAngle:Number(6))};using var nativeFile=File.OpenRead(Path.Combine(Path.GetDirectoryName(csv)!,parts[0]));var expected=VisionIO.BmpReader.Read(nativeFile);var actual=RoiRasterizer.CreateMask([region],size,size);int differences=expected.Pixels.ToArray().Zip(actual).Count(p=>p.First!=p.Second);rasterResults.Add(new{File=parts[0],Differences=differences});Check(differences==0,"source-derived annular sector raster "+parts[0]);}}File.WriteAllText("analysis/full-audit/sector-raster-comparison.json",JsonSerializer.Serialize(rasterResults,new JsonSerializerOptions{WriteIndented=true}));
 Check(Execute([rect with{CenterX=1000,CenterY=1000}]).Status==ModuleStatus.Failed,"source ROI outside-image error is preserved");values["OutputMaskImage"]=JsonSerializer.SerializeToElement(true);checkMask();void checkMask(){var r=Execute([rect]);Check(r.Outputs["OutMask"].As<GrayImage>().Pixels.ToArray().Count(v=>v!=0)==48,"output-mask enable emits actual ROI mask");}values["OutputMaskImage"]=JsonSerializer.SerializeToElement(false);
 var editor=new GroupRoiEditor([],ImageBinaryPlugin.RoiCapabilities);editor.SetImage(image);editor.SetDrawKind(RoiKind.SectorRing);editor.BeginPointer(new(8,8));editor.UpdatePointer(new(14,8));editor.EndPointer(new(14,8));Check(editor.Regions.Single().Kind==RoiKind.SectorRing&&editor.Regions.Single().InnerRadius==3,"draw sector ring actual WPF control");Check(Execute(editor.Regions).Outputs["ProcessedPixels"].As<long>()>0,"drawn sector consumed by real algorithm");editor.ParametersExpanded=true;var captureRoot=new Border{Background=Brushes.White,Child=editor};var window=new Window{Content=captureRoot,Width=1100,Height=700,ShowInTaskbar=false,Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();window.UpdateLayout();window.Dispatcher.Invoke(()=>{},System.Windows.Threading.DispatcherPriority.ApplicationIdle);var bitmap=new RenderTargetBitmap((int)captureRoot.ActualWidth,(int)captureRoot.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(captureRoot);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create("analysis/full-audit/roi-binary-sector-editor.png"))encoder.Save(file);window.Close();
 var registry=new ModuleRegistry();BuiltinModules.RegisterAll(registry);registry.Register(plugin.Descriptor,plugin.CreateRuntime);var doc=new GraphEditorDocument(registry);var group=doc.AddNode(WorkflowCalls.ModuleId,WorkflowCalls.Version,0,0);var body=doc.EnterOwnedGroup(group);var source=doc.AddNode("vision.image-file","1.0.0",0,0,new(){["Path"]=JsonSerializer.SerializeToElement(Path.Combine(root,"input.bmp"))});var b=doc.AddNode(ImageBinaryPlugin.Id,"1.0.0",200,0);doc.Connect(source,"Image",b,"Image");doc.SetProcedureToolConfiguration(body,b,values,[rect]);doc.SetWorkflowConfiguration(body,new(){Outputs=[new("out","Result",DataKind.GrayImage,b,"Image")],RunParameters=[new("roi",b,"RoiType","检测区域")]});doc.LeaveGroup();var run1=new SolutionExecutor(registry).RunAsync(new(doc.Document,doc.BaseDirectory),"main").GetAwaiter().GetResult();if(run1.Status!=SessionStatus.Success)Console.WriteLine(string.Join(";",run1.Nodes.Select(n=>n.Message)));Check(run1.Status==SessionStatus.Success,"owned Group executes real binary tool");var first=run1.Nodes.Single(n=>n.NodeId==group).Outputs["Result"].As<GrayImage>();doc.SetGroupRunComplexValue(body,"roi",new Dictionary<string,JsonElement>(),[rect with{Width=4}]);var run2=new SolutionExecutor(registry).RunAsync(new(doc.Document,doc.BaseDirectory),"main").GetAwaiter().GetResult();Check(run2.Status==SessionStatus.Success,"Group proxy ROI edit executes");var second=run2.Nodes.Single(n=>n.NodeId==group).Outputs["Result"].As<GrayImage>();Check(!first.Pixels.SequenceEqual(second.Pixels),"Group proxy changes actual output pixels");doc.Undo();Check(doc.Document.Procedures.Single(p=>p.Id==body).Nodes.Single(n=>n.Id==b).Rois!.Single().Width==8,"ROI atomic edit undo");
 var roiSpec=plugin.Descriptor.Parameters.Single(p=>p.Name=="RoiType");bool saved=false;var dedicated=(ImageBinaryParameterWindow)plugin.CreateParameterEditor(new(node,roiSpec,image,(fields,regions)=>{doc.SetGroupRunComplexValue(body,"roi",fields,regions);saved=true;}));dedicated.ShowInTaskbar=false;dedicated.WindowStartupLocation=WindowStartupLocation.Manual;dedicated.Left=-20000;dedicated.Top=-20000;dedicated.Dispatcher.BeginInvoke(new Action(()=>{dedicated.Roi.SetDrawKind(RoiKind.Rectangle);dedicated.Roi.BeginPointer(new(2,2));dedicated.Roi.UpdatePointer(new(7,7));dedicated.Roi.EndPointer(new(7,7));var button=Descendants(dedicated).OfType<Button>().Single(b=>Equals(b.Tag,"ImageBinaryRoiConfirm"));button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));Check(dedicated.ShowDialog()==true&&saved,"dedicated real-plugin ROI dialog Apply closes and commits Group proxy");Check(doc.Document.Procedures.Single(p=>p.Id==body).Nodes.Single(n=>n.Id==b).Rois!.Single().Width==5,"dedicated UI actual geometry persisted");
 TemplateAndWindowChecks.Run(app,Check,plugin,image,node,values);
 RealBinaryHostChecks.Run(Check);NormalizedRoiChecks.Run();
 Console.WriteLine("ROI real-tool checks: "+count);app.Shutdown();}
